<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
import DashboardLayout from '../layouts/DashboardLayout.vue';
import type { School, SchoolDashboard } from '../types';
const props=defineProps<{page:string;title:string;schools:School[];selectedSchool:School|null;dashboard:SchoolDashboard|null;kind:string;document:Record<string,any>;baseUrl:string}>();
const snapshot=props.document.snapshot;
const money=(n:number)=>new Intl.NumberFormat('en-PK',{style:'currency',minimumFractionDigits:2,maximumFractionDigits:2,currency:snapshot.currency??props.document.currency}).format(n/100);
function print(){window.print();}
</script>
<template><Head :title="`${title} ${document.number}`"/><DashboardLayout :page="page" :title="title" :schools="schools" :selected-school="selectedSchool" :dashboard="dashboard"><div class="academic-actions no-print"><button class="academic-button" @click="print">Print / reprint A4</button><Link class="secondary-button" :href="baseUrl+(kind==='receipt'?'/payments':'/invoices')">Back</Link></div><article class="finance-document panel"><header><img :src="snapshot.school.logo" alt="School emblem"/><div><h1>{{ snapshot.school.name }}</h1><p>{{ snapshot.school.address }} {{ snapshot.school.city }}</p><p>{{ snapshot.school.phone }}</p></div><div><h2>{{ kind==='receipt'?'PAYMENT RECEIPT':'STUDENT INVOICE' }}</h2><strong>{{ document.number }}</strong></div></header><p class="finance-watermark" v-if="document.status==='reversed'||document.status==='voided'">{{ document.status.toUpperCase() }}</p><p v-if="document.status==='draft'" class="finance-watermark">DRAFT · NOT POSTED</p><div class="finance-document-info"><p><strong>Student</strong><span>{{ snapshot.student_name }}</span></p><p><strong>Admission number</strong><span>{{ snapshot.admission_number }}</span></p><p><strong>Class / section</strong><span>{{ snapshot.class }} / {{ snapshot.section }}</span></p><p><strong>{{ kind==='receipt'?'Payment date':'Issue / due dates' }}</strong><span>{{ kind==='receipt'?snapshot.paid_on:document.issued_on+' / '+document.due_on }}</span></p><p><strong>Status</strong><span>{{ document.display_status??document.status }}</span></p><p v-if="kind==='receipt'"><strong>Payment method</strong><span>{{ snapshot.method.replaceAll('_',' ') }} · manually recorded</span></p></div><div class="table-scroll"><table v-if="kind==='receipt'"><thead><tr><th>Invoice reference</th><th>Amount allocated</th><th>Balance at payment</th></tr></thead><tbody><tr v-for="a in snapshot.allocations" :key="a.invoice"><td>{{ a.invoice }}</td><td>{{ money(a.amount_minor) }}</td><td>{{ money(a.remaining_minor) }}</td></tr></tbody></table><table v-else><thead><tr><th>Fee item</th><th>Amount</th><th>Discount</th><th>Net</th></tr></thead><tbody><tr v-for="i in document.items" :key="i.id"><td>{{ i.description }}</td><td>{{ money(i.amount_minor) }}</td><td>{{ money(i.discount_minor) }}</td><td>{{ money(i.amount_minor-i.discount_minor) }}</td></tr></tbody></table></div><div class="finance-document-totals"><template v-if="kind==='receipt'"><p><span>Amount paid</span><strong>{{ money(snapshot.amount_minor) }}</strong></p><p><span>Unallocated credit at payment</span><strong>{{ money(snapshot.unallocated_minor) }}</strong></p><p><span>Refunds posted since receipt</span><strong>{{ money(document.refund_minor) }}</strong></p></template><template v-else><p><span>Original invoice total</span><strong>{{ money(document.total_minor) }}</strong></p><p><span>Separately posted late fee</span><strong>{{ money(document.penalty) }}</strong></p><p><span>Net allocated payment</span><strong>{{ money(document.paid) }}</strong></p><p><span>Outstanding balance</span><strong>{{ money(document.outstanding) }}</strong></p></template></div><p v-if="document.reason">Reversal reason: {{ document.reason }}</p><p v-if="document.void_reason">Void reason: {{ document.void_reason }}</p><p class="finance-note">{{ kind==='receipt'?snapshot.verification:'Issued amounts are historical snapshots. Penalties and payment balances are listed separately.' }}</p><footer><span>Authorized signature __________________</span><small>Local development preview · {{ kind==='receipt'?'Historical receipt; balances shown as at payment':'School fee billing' }}</small></footer></article></DashboardLayout></template>
